_BUILD = None
_BUILT_FROM = None   # the C source's size and modification time when _BUILD was made
_CACHE = {}


def _source_stamp():
    """Size and modification time of the C source, or None if it is not there."""
    try:
        st = (LESSON_DIR / C_SRC).stat()
    except OSError:
        return None
    return (st.st_size, st.st_mtime_ns)


def build(verbose: bool = True):
    """Compile the C source with make.

    Cached: the compiler runs once per session, and again only when the C source changes. So
    after you edit lesson.c, re-running any cell below rebuilds it and forgets every answer
    the old binary gave — you are never graded against yesterday's build.
    """
    global _BUILD, _BUILT_FROM
    stamp = _source_stamp()
    if _BUILD is None or stamp != _BUILT_FROM:
        for key in [k for k in _CACHE if isinstance(k, tuple)]:   # the binary's old answers
            del _CACHE[key]
        # A rebuild after an edit is forced (-B): some makes compare whole seconds, and an edit
        # saved in the same second as the last build would otherwise look up to date.
        force = ["-B"] if _BUILD is not None else []
        try:
            proc = subprocess.run(
                ["make", *force, "-C", str(LESSON_DIR), f"PYTHON={sys.executable}",
                 f"SRC={C_SRC}", f"BIN={BIN}"],
                capture_output=True, text=True, timeout=600)
            _BUILD = (proc.returncode == 0, (proc.stdout + proc.stderr).strip())
        except (OSError, subprocess.TimeoutExpired) as exc:   # no make, or no compiler
            _BUILD = (False, f"could not run make ({exc}). This lesson needs make and a C "
                             "compiler (clang or gcc) on the machine running the notebook.")
        _BUILT_FROM = stamp
    ok, out = _BUILD
    if verbose:
        print("build OK" if ok else "BUILD FAILED\n" + out)
    return ok, out


def run_c(*args, timeout: int = 300) -> str:
    """Run the compiled binary and return its stdout.

    Exit code 2 means one of the four C exercises is still a stub, so it is re-raised as
    NotImplementedError — the grader then reports TODO instead of an error.
    """
    ok, out = build(verbose=False)
    if not ok:
        raise RuntimeError("the C build failed; run build() to see the compiler output\n" + out)
    proc = subprocess.run([str(LESSON_DIR / BIN), *args],
                          cwd=LESSON_DIR, capture_output=True, text=True, timeout=timeout)
    if proc.returncode == 2:
        raise NotImplementedError(proc.stderr.strip() or "a C exercise is still a stub")
    if proc.returncode != 0:
        raise RuntimeError(f"{BIN} {' '.join(args)} exited {proc.returncode}\n"
                           f"{proc.stderr.strip()}")
    return proc.stdout


def cached(*args) -> str:
    """run_c, but each distinct command line is executed once per build of the binary."""
    build(verbose=False)   # an edited lesson.c is rebuilt here, and its old answers dropped
    if args not in _CACHE:
        _CACHE[args] = run_c(*args)
    return _CACHE[args]


def metrics(text: str) -> dict:
    """Parse the binary's `@ key=value` report lines into a dict of floats."""
    return {k: float(v) for k, v in
            (line[2:].split("=", 1) for line in text.splitlines() if line.startswith("@ "))}


def rows(text: str, tag: str) -> list:
    """Parse the binary's `<tag> v1 v2 ...` lines into a list of lists of floats."""
    return [[float(v) for v in line.split()[1:]]
            for line in text.splitlines() if line.startswith(tag + " ")]


def make_test():
    """Run the C self-test — what `make test` runs. Returns (exit code, combined output).

    The binary is built with make and then invoked directly, so its OWN exit code survives:
    make reports any failed recipe as 2, which would make a real failure (the binary's 1)
    indistinguishable from an unfinished stub (the binary's 2).
    """
    ok, out = build(verbose=False)
    if not ok:
        return 1, out
    proc = subprocess.run([str(LESSON_DIR / BIN), "selftest"],
                          cwd=LESSON_DIR, capture_output=True, text=True, timeout=600)
    return proc.returncode, (proc.stdout + proc.stderr).strip()


_FAILED_CHECKS: list = []

# The exercises, in the order you meet them, and the functions each one asks you to write.
